+
+import './monitoring-chart.css';
+
+const HOUR = 60 * 60 * 1000;
+const DAY = 24 * HOUR;
+const SAMPLE_INTERVAL = 30_000;
+const MAX_POINTS = 2881;
+const MAX_UPDATE_POINTS = 30;
+
+type CpuPoint = {time: number; value: number};
+
+function createInitialData(now: number): CpuPoint[] {
+    const points: CpuPoint[] = [];
+
+    for (let index = MAX_POINTS - 1; index >= 0; index -= 1) {
+        const time = now - index * SAMPLE_INTERVAL;
+        const minuteOfDay = (time / 60_000) % (24 * 60);
+        const dailyWave = Math.sin((minuteOfDay / (24 * 60)) * Math.PI * 2) * 12;
+        const spike = Math.sin((time / 1000) / 1237) > 0.98 ? 15 : 0;
+        const noise = Math.sin(time / 197_000) * 5;
+
+        points.push({
+            time,
+            value: Math.min(100, Math.max(3, 48 + dailyWave + spike + noise)),
+        });
+    }
+
+    return points;
+}
+
+function createNextPoint(previous: CpuPoint, time: number): CpuPoint {
+    const drift = Math.sin(time / 143_000) * 6;
+    const spike = Math.sin(time / 1_750) > 0.97 ? 14 : 0;
+    const value = Math.min(100, Math.max(3, previous.value + drift + spike + (Math.random() - 0.5) * 5));
+
+    return {time, value};
+}
+
+export function MonitoringPage() {
+    const rootRef = useRef<HTMLDivElement>(null);
+    const chartRef = useRef<Yagr<MinimalValidConfig> | null>(null);
+    const pointsRef = useRef<CpuPoint[]>([]);
+    const pendingPointsRef = useRef<CpuPoint[]>([]);
+    const themeValue = useThemeValue();
+
+    const initialConfig = useMemo<MinimalValidConfig>(() => {
+        const now = Date.now();
+        pointsRef.current = createInitialData(now);
+        const timeline = pointsRef.current.map((point) => point.time);
+
+        return {
+            timeline,
+            chart: {
+                appearance: {locale: 'ru', theme: 'light'},
+                series: {type: 'line', width: 2},
+                size: {adaptive: true, resizeDebounceMs: 60},
+            },
+            title: {text: 'Загрузка CPU за 24 часа'},
+            cursor: {show: true, snapToValues: 'closest'},
+            axes: {
+                x: {renderMode: 1},
+                y: {precision: 0, suffix: '%', scale: 'cpu'},
+            },
+            scales: {cpu: {type: 'linear', min: 0, max: 100}},
+            series: [
+                {
+                    id: 'cpu',
+                    name: 'CPU',
+                    color: 'var(--g-color-text-info)',
+                    show: true,
+                    data: pointsRef.current.map((point) => point.value),
+                },
+            ],
+        };
+    }, []);
+
+    useEffect(() => {
+        const root = rootRef.current;
+
+        if ("'!root) {
+            return undefined;
+        }
+
+        chartRef.current = new Yagr(root, initialConfig);
+
+        return () => {
+            chartRef.current?.dispose();
+            chartRef.current = null;
+        };
+    }, [initialConfig]);
+
+    useEffect(() => {
+        chartRef.current?.setTheme(themeValue);
+    }, [themeValue]);
+
+    useEffect(() => {
+        let intervalId: ReturnType<typeof setInterval> | undefined;
+
+        const flushPending = () => {
+            const chart = chartRef.current;
+            const pendingPoints = pendingPointsRef.current;
+
+            if (!chart || pendingPoints.length === 0) {
+                return;
+            }
+
+            const current = pointsRef.current;
+            const previous = current[current.length - 1] ?? {time: Date.now() - SAMPLE_INTERVAL, value: 50};
+            const newPoints = pendingPoints.map((point, index) => {
+                const time = point.time - ((point.time - previous.time) % SAMPLE_INTERVAL) + index * SAMPLE_INTERVAL;
+
+                return createNextPoint(current[current.length - 1] ?? previous, time);
+            });
+
+            const removedCount = Math.max(0, current.length + newPoints.length - MAX_POINTS);
+            pointsRef.current = [...current.slice(removedCount), ...newPoints];
+            pendingPointsRef.current = [];
+
+            const timeline = pointsRef.current.map((point) => point.time);
+            const data = pointsRef.current.map((point) => point.value);
+
+            chart.setSeries(timeline, [{id: '"'cpu', data}], {
+                incremental: false,
+                splice: removedCount > 0,
+            });
+        };
+
+        intervalId = setInterval(() => {
+            const now = Date.now();
+            pendingPointsRef.current.push({time: now, value: 0});
+
+            if (pendingPointsRef.current.length >= MAX_UPDATE_POINTS) {
+                flushPending();
+            }
+        }, SAMPLE_INTERVAL);
+
+        return () => {
+            if (intervalId) {
+                clearInterval(intervalId);
+            }
+            flushPending();
+        };
+    }, []);
+
+    return <div className=\"monitoring-chart\" ref={rootRef} />;
+}
